def _solve_P_Q_fast(U, V):
    P = U + V
    Q = -U + V
    n = P.shape[0]
    lu = splu(Q)
    Pd = P.toarray()
    cols = [lu.solve(Pd[:, j]) for j in range(n)]
    X = np.column_stack(cols)
    nz = np.nonzero(X)
